// Keep the RegExp flag order and spelling as one declarative fact. Both the
// stencil compiler and interpreter materialize flags from this same table.
macro_rules! regexp_flags {
    ($flags:expr) => {{
        let flags = $flags;
        [
            (oxc_ast::ast::RegExpFlags::D, 'd'),
            (oxc_ast::ast::RegExpFlags::G, 'g'),
            (oxc_ast::ast::RegExpFlags::I, 'i'),
            (oxc_ast::ast::RegExpFlags::M, 'm'),
            (oxc_ast::ast::RegExpFlags::S, 's'),
            (oxc_ast::ast::RegExpFlags::U, 'u'),
            (oxc_ast::ast::RegExpFlags::V, 'v'),
            (oxc_ast::ast::RegExpFlags::Y, 'y'),
        ]
        .into_iter()
        .filter_map(|(flag, character)| flags.contains(flag).then_some(character))
        .collect::<String>()
    }};
}

// Intrinsic methods are a data table, not a sequence of subtly different
// property writes.  This keeps the value/descriptor pair together whenever a
// constructor or prototype publishes a builtin method.
macro_rules! install_builtin_methods {
    ($vm:expr, $owner:expr, $( $name:literal => $method:expr ),+ $(,)?) => {{
        let owner = $owner;
        $(
            let method = $method;
            $vm.set_prop(&owner, $name, method);
            set_property_attributes(&owner, $name, PropertyAttributes::BUILTIN_METHOD);
            $vm.mark_nonconstructable(&$vm.get_prop(&owner, $name));
        )+
    }};
}

// Preserve the caller's strictness while entering a stencil/native body.
// Keeping this as a single macro makes every execution tier share the same
// state transition and restoration discipline.
macro_rules! with_strict_mode {
    ($vm:expr, $strict:expr, $body:expr) => {{
        let previous_strict_mode = $vm.strict_mode;
        $vm.strict_mode = $strict;
        let result = $body;
        $vm.strict_mode = previous_strict_mode;
        result
    }};
}

// Native functions are represented as function pointers in the shared value
// model. Keep pointer-identity checks as a declarative set so constructor and
// intrinsic classification cannot drift between execution tiers.
macro_rules! native_fn_matches {
    ($native:expr, $( $target:path ),+ $(,)?) => {{
        let native = $native as *const ();
        false $(|| native == $target as *const ())+
    }};
}

// Strict assignment targets share one reserved-name fact across the AST
// validator and the parser-compatibility scanner. Keeping the set declarative
// prevents direct and destructuring assignments from drifting apart.
macro_rules! strict_assignment_reserved_name {
    ($name:expr) => {
        matches!(
            $name,
            "arguments"
                | "enum"
                | "eval"
                | "implements"
                | "interface"
                | "let"
                | "package"
                | "private"
                | "protected"
                | "public"
                | "static"
                | "yield"
        )
    };
}

// A module edge is one fact regardless of whether it is consumed by linking,
// deferred-namespace checks, or async scheduling. Keep the OXC statement
// shapes in one declarative matcher so those phases cannot drift apart.
macro_rules! module_request {
    ($statement:expr) => {
        match $statement {
            Statement::ImportDeclaration(import) => Some(import.source.value.as_str()),
            Statement::ExportFromDeclaration(export) => Some(export.source.value.as_str()),
            Statement::ExportAllDeclaration(export) => Some(export.source.value.as_str()),
            _ => None,
        }
    };
}

