/// Declare the data-method portion of a builtin prototype once.  The
/// bootstrap has two realm paths (full and reduced), so keeping the method
/// list as data prevents one path from silently missing a semantic operation.
macro_rules! install_native_methods {
    ($vm:expr, $prototype:expr, $( $name:literal => $native:ident / $length:expr ),+ $(,)?) => {{
        let prototype = $prototype;
        $(
            let method = $vm.native_named($native, $name, $length);
            $vm.set_prop(&prototype, $name, method.clone());
            set_property_attributes(&prototype, $name, PropertyAttributes::BUILTIN_METHOD);
            $vm.mark_nonconstructable(&method);
        )+
    }};
}

// Collection iterator prototypes differ only by their tag, next primitive,
// and destination slot. Keep those facts in one declaration so Map and Set
// cannot drift in descriptors or iterator identity.
macro_rules! install_collection_iterator_prototype {
    ($vm:expr, $slot:ident, $next:ident, $tag:literal) => {{
        let iterator_prototype = $vm.object($vm.default_object_prototype());
        let next = $vm.native_named($next, "next", 0);
        $vm.mark_nonconstructable(&next);
        $vm.set_prop(&iterator_prototype, "next", next);
        let iterator_key = $vm.well_known_symbol_key("iterator");
        $vm.set_prop(&iterator_prototype, &iterator_key, $vm.native(native_iterator_self));
        let tag_key = $vm.well_known_symbol_key("toStringTag");
        $vm.set_prop(&iterator_prototype, &tag_key, Value::string_value($tag));
        set_property_attributes(&iterator_prototype, &tag_key, PropertyAttributes { writable: false, enumerable: false, configurable: true });
        $vm.$slot = iterator_prototype.as_object();
    }};
}

// Every typed-array constructor is the same semantic constructor with a
// different element kind and width. Keep that metadata as one declaration so
// construction, reflection, and indexed conversion consume the same record.
macro_rules! install_typed_array_constructor_metadata {
    ($vm:expr, $constructor:expr, $name:expr, $bytes:expr) => {{
        let constructor = $constructor.clone();
        let name = $name;
        let bytes = $bytes;
        $vm.set_prop(&constructor, "\0typed-array-kind", Value::string_value(name));
        $vm.set_prop(&constructor, "\0typed-array-bytes", Value::Number(bytes as f64));
        $vm.set_prop(&constructor, "BYTES_PER_ELEMENT", Value::Number(bytes as f64));
        set_property_attributes(
            &constructor,
            "BYTES_PER_ELEMENT",
            PropertyAttributes::BUILTIN_CONSTANT,
        );
    }};
}
